const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));

// Shared, read-only presentation: no requests, adoption or automatic retry.
export function writingQualityPanel(value,{references=[],scrollKey='writing-quality',completed=false}={}){
  const quality=value&&typeof value==='object'&&!Array.isArray(value)?value:null;
  const rows=value=>Array.isArray(value)?value.filter(row=>row&&typeof row==='object'&&!Array.isArray(row)).slice(0,200):[];
  const count=value=>Number.isSafeInteger(value)&&value>=0&&value<=10000?value:0;
  // Review prose can legitimately discuss economic cost, research budgets,
  // statistical models or providers. Redact only concrete runtime identifiers,
  // credential-shaped values and backend API endpoints, never manuscript quotes.
  const privateDiagnostic=/(?:\b(?:apiKey|api_key|accessKeySecret|ANTHROPIC_API_KEY|OPENAI_API_KEY|maxBudgetUsd|maxCostUsd|maxOutputTokens|maxTotalTokens|maxTurns|max_tokens|max_turns|baseURL|settings_version)\b|\bsk-[a-z0-9_-]{20,}\b|https?:\/\/(?:api\.(?:anthropic|openai)\.com|dashscope(?:-intl)?\.aliyuncs\.com|127\.0\.0\.1|localhost)(?::\d+)?(?:\/[^\s]*)?)/i;
  const text=(value,fallback='部分检查尚未完成，请结合原始资料人工核对。')=>typeof value==='string'&&value.trim()?privateDiagnostic.test(value)?fallback:value.trim().slice(0,1500):fallback;
  const reasonText=(row,fallback)=>['budget_exhausted','budget_exceeded','token_budget','cost_budget'].includes(row.reasonCode)?'本批检查未完成。':text(row.reason,fallback);
  const citationLabels={matched:'题录匹配',conflict:'信息待核对',not_found:'暂未找到',unverified:'未核验',unavailable:'暂不可用'};
  const citationNotes={matched:'题录信息已对应；引文与正文论断的关系仍需核对。',conflict:'部分题录信息存在差异，请对照原始文献核对。',not_found:'本次来源暂未找到匹配记录，不代表文献不存在或虚假。',unverified:'此条尚未进行外部题录核验。',unavailable:'本次题录核验暂未完成。'};
  const citations=rows(quality?.citations?.items),summary=quality?.citations?.summary||{},refs=new Map(rows(references).map(row=>[row.id,row.title]));
  const findings=rows(quality?.consistency?.findings),hasConsistency=Array.isArray(quality?.consistency?.findings)&&quality.consistency.status!=='unavailable',reviews=rows(quality?.reviews);
  // Older saved drafts used status as the outcome; new runners keep transport
  // completion separate from whether the review found an issue.
  const reviewed=reviews.filter(row=>row.status==='completed'||['review_required','no_ai_findings'].includes(row.status)),unfinished=reviews.filter(row=>!reviewed.includes(row));
  const aiFindings=reviewed.flatMap(review=>rows(review.findings)).slice(0,100);
  const status=quality?.stale?'正文已修改':({completed:'检查记录已保存',partial:'部分检查完成',unavailable:'检查暂未完成'}[quality?.status]||(completed?'检查记录未保存':'生成后查看'));
  const categoryLabels={duplicate_title:'重复标题',unresolved_placeholder:'待补充事项',unknown_citation:'引用来源待核对',citation_list_mismatch:'引用标记待核对',uncited_source:'来源标记待核对',duplicate_paragraph:'段落重复',logic:'论证衔接',terminology:'术语一致性',claim_scope:'结论范围',method_result_consistency:'方法与结果',source_support:'引文依据',structure:'章节结构'};
  const findingList=(list,kind)=>list.length?`<ol class="thesis-quality-findings">${list.map(row=>`<li><div><b>${escape(row.sectionTitle||'对应章节')}</b><small>${escape(categoryLabels[row.category]||'待人工核对')} · ${kind}</small></div>${typeof row.quote==='string'&&row.quote?`<blockquote>${escape(row.quote.slice(0,500))}</blockquote>`:''}<p>${escape(text(row.explanation,'此处需要结合前后章节与原始资料核对。'))}</p>${typeof row.suggestion==='string'&&row.suggestion.trim()?`<p class="thesis-quality-suggestion"><b>建议：</b>${escape(text(row.suggestion))}</p>`:''}</li>`).join('')}</ol>`:'';
  const limitations=[quality?.limitations,quality?.citations?.limitations,quality?.consistency?.limitations,...reviews.map(row=>row.limitations)].flatMap(value=>Array.isArray(value)?value:[]).filter(value=>typeof value==='string'&&value.trim());
  const uniqueLimitations=[...new Set(limitations.map(value=>text(value)))].slice(0,16);
  const date=quality?.checkedAt&&Number.isFinite(Date.parse(quality.checkedAt))?new Date(quality.checkedAt).toLocaleString('zh-CN'):'';
  const reviewStatus=unfinished.length?'部分辅助审校未能完成，请结合已完成记录核对。':reviewed.length&&reviewed.every(row=>(row.outcome||row.status)==='no_ai_findings')?'在本次提供的范围内，辅助审校未提出可定位问题；不代表全文没有问题。':reviewed.length?'以下为辅助审校建议，请结合原文判断。':'尚无独立辅助审校记录。';
  const coverage=quality?.coverage,characters=value=>Number.isSafeInteger(value)&&value>=0&&value<=200000000?value:0;
  const hasCoverage=coverage&&Number.isSafeInteger(coverage.totalCharacters)&&coverage.totalCharacters>=0&&Number.isSafeInteger(coverage.reviewedCharacters)&&coverage.reviewedCharacters>=0;
  const reviewScope=hasCoverage?`辅助审校已检查 ${characters(coverage.reviewedCharacters).toLocaleString('zh-CN')} / ${characters(coverage.totalCharacters).toLocaleString('zh-CN')} 个正文字符，完成 ${count(coverage.reviewedBatches)} / ${count(coverage.totalBatches)} 组。${coverage.complete===true?'各正文片段检查已完成，跨片段关系仍需人工核对。':'辅助审校未覆盖全部正文。'}`:reviews.length?`本次审校记录涉及 ${Math.max(...reviews.map(row=>count(row.checkedSections)))} 个章节单元。${reviews.some(row=>row.excerpted===true)?'仅检查提供的正文片段，未覆盖完整全文。':''}`:'';
  return `<details class="thesis-quality-results writing-quality-panel" data-writing-quality-panel data-thesis-quality-panel data-thesis-view-key="quality"><summary data-writing-quality-summary data-thesis-quality-summary tabindex="0"><b>生成检查</b><span>${status}</span></summary><div data-writing-quality-scroll data-thesis-quality-scroll data-scroll-key="${escape(scrollKey)}" tabindex="0" role="region" aria-label="生成检查记录">${quality?`${quality.stale?'<p class="thesis-quality-stale" role="status">正文已修改，以下为生成时检查记录。</p>':''}${date?`<p class="thesis-quality-date">检查时间：${escape(date)}</p>`:''}<section class="thesis-quality-citations"><h4>参考文献题录核验</h4><div class="thesis-quality-statistics">${Object.entries(citationLabels).map(([key,label])=>`<span><b>${count(summary[key])}</b>${label}</span>`).join('')}</div>${citations.length?`<ol>${citations.map((row,index)=>{const state=Object.hasOwn(citationLabels,row.metadataStatus)?row.metadataStatus:'unverified';return `<li><div><b>${escape(refs.get(row.id)||'参考文献 '+(index+1))}</b><small class="thesis-quality-status status-${state}">${citationLabels[state]}</small></div><p>${escape(reasonText(row,citationNotes[state]))}</p></li>`;}).join('')}</ol>`:'<p>当前没有逐条题录核验记录；未提供可核验标识的文献仍需人工核对。</p>'}<p class="thesis-quality-boundary">题录核验不代表已查证全文、引文支持关系或研究真实性；未找到也不能判定文献虚假。</p></section><section><h4>正文规则检查</h4>${findingList(findings,'规则检查')||`<p>${hasConsistency?'本次规则检查未列出问题；不代表事实与研究质量已经核实。':'正文规则检查尚未完成。'}</p>`}${quality.consistency?.truncated===true?`<p>共记录 ${count(quality.consistency.totalFindings)} 项问题，当前仅展示部分记录。</p>`:''}</section><section><h4>全文辅助审校</h4><p>${reviewStatus}</p>${reviewScope?`<p>${reviewScope}</p>`:''}${unfinished.length?`<ul class="thesis-quality-unfinished">${unfinished.map(row=>`<li>${row.status==='not_started'?'部分正文尚未开始辅助审校。':'部分正文辅助审校未完成。'}${escape(reasonText(row,''))}</li>`).join('')}</ul>`:''}${findingList(aiFindings,'辅助审校')}</section>${uniqueLimitations.length?`<section class="thesis-quality-limitations"><h4>检查范围与局限</h4><ul>${uniqueLimitations.map(value=>`<li>${escape(value)}</li>`).join('')}</ul></section>`:''}`:completed?'<p>本次生成检查记录未保存，不能据此确认检查已完成。请人工核对事实、引用和研究结果。</p>':'<p>生成后，参考文献题录核验与全文审校记录会显示在这里。</p><p>检查不会自动修改正文，仍需核对事实、引用和研究结果。</p>'}</div></details>`;
 }
